DROP VIEW IF EXISTS replset.vw_month_writeoffs CASCADE;  CREATE OR REPLACE VIEW replset.vw_month_writeoffs AS  SELECT date_trunc('month'::text, date_period) AS repmonth,     orgs_code,     orgs_name,     shop_code,     shop_name,     expwo_code,     expwo_name,     sum(amount) AS amount    FROM mvw_writeoffs   GROUP BY (date_trunc('month'::text, date_period)), orgs_code, orgs_name, shop_code, shop_name, expwo_code, expwo_name;
